void floydWarshall(vector<vector<int>>& graph) {
    int n = graph.size();

    for (int k = 0; k < n; ++k) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (graph[i][k] != INT_MAX && graph[k][j] != INT_MAX) {
                    graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j]);
                }
            }
        }
    }
}

int main() {
    int n;
    cout << "Enter the number of vertices: ";
    cin >> n;

    vector<vector<int>> graph(n, vector<int>(n, INT_MAX));

    cout << "Enter the adjacency matrix (enter 0 for no direct edge):" << endl;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> graph[i][j];
            if (i == j) {
                graph[i][j] = 0;
            }
        }
    }

    floydWarshall(graph);

    cout << "Shortest distances between every pair of vertices:" << endl;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (graph[i][j] == INT_MAX) {
                cout << "INF ";
            } else {
                cout << graph[i][j] << "   ";
            }
        }
        cout << endl;
    }

    return 0;
}

